package com.testgen.api.entity; import jakarta.persistence.*; import java.time.Instant; @Entity @Table(name="test_results") public class TestResult { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) public Long id; @ManyToOne public Project project; public String name; @Column(columnDefinition="LONGTEXT") public String data; public Instant createdAt=Instant.now(); }